// Battery for the just-bash-over-workspace-fs evaluation. Every case is a script run with the
// workspace root as its cwd, after FIXTURE. Written so that GNU bash 5.1 + coreutils is the
// reference; where a tool is absent there (rg, tree) the case still records what just-bash does.
const r = (s, ...v) => String.raw(s, ...v).replaceAll('\\u007b', '{');

export const FIXTURE = r`rm -rf proj; mkdir -p proj/src/lib proj/docs proj/node_modules/pkg proj/empty
printf 'hello\nworld\nfoo bar\n' > proj/a.txt
printf 'alpha\nbeta\ngamma\nbeta\nalpha\nbeta\n' > proj/words.txt
printf 'line1\nTODO: fix this\nline3\nTODO: another\n' > proj/src/main.js
printf 'export const x = 1;\n// TODO later\n' > proj/src/lib/util.js
printf '# Title\n\nSome docs with TODO.\n' > proj/docs/README.md
printf '{"name":"pkg","version":"1.0.0"}\n' > proj/node_modules/pkg/package.json
printf 'name,age,city\nalice,30,paris\nbob,25,london\ncarol,35,paris\n' > proj/data.csv
printf 'a b c\n1 2 3\n4 5 6\n' > proj/nums.txt
printf 'no newline at end' > proj/nonl.txt
printf '#!/bin/sh\necho script ran: $1\n' > proj/run.sh
printf 'tab\tseparated\tvalues\nsecond\trow\there\n' > proj/tabs.txt
`;

